    margin-top: 0;
}
.module h3 {
    margin-bottom: 0.5rem;
}
.module p {
    margin-bottom: 1rem;
}
.module a {
    text-decoration: none;
    color: #222;
}
.module a:hover {
    text-decoration: underline;
}
.module .content {
    background-color: #fff;
    padding: 1rem;
